css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); }
.loader span { position: absolute; border-radius: 9999px; border: calc(var(--loader-size) * .05) solid transparent; }
.loader span:nth-child(1) { top: 0; bottom: 0; left: 0; right: 0; border-top-color: var(--loader-color); animation: twSpin var(--loader-speed) linear infinite; }
.loader span:nth-child(2) { top: 18%; bottom: 18%; left: 18%; right: 18%; border-right-color: var(--loader-secondary-color); animation: twSpinBack calc(var(--loader-speed) * .85) linear infinite; }
.loader span:nth-child(3) { top: 36%; bottom: 36%; left: 36%; right: 36%; border-bottom-color: var(--loader-color); animation: twSpin calc(var(--loader-speed) * .7) linear infinite; }
@keyframes twSpin { to { transform: rotate(360deg); } }
@keyframes twSpinBack { to { transform: rotate(-360deg); } }
